$\begin{aligned} x & =\sin t \\ \therefore \quad \frac{d x}{d t} & =\cos t \\ y & =a e^{t \sqrt{2}}+b e^{t \sqrt{2}} \\ & =e^{t \sqrt{2}}(a+b)\end{aligned}\begin{array}{ll}\therefore & \frac{\mathrm{d} y}{\mathrm{dt}}=(\mathrm{a}+\mathrm{b}) \cdot \mathrm{e}^{\mathrm{t} \sqrt{2}} \cdot \sqrt{2} \\ \therefore & \frac{\mathrm{~d} y}{\mathrm{~d} x}=\frac{\frac{\mathrm{d} y}{\mathrm{dt}}}{\frac{\mathrm{d} x}{\mathrm{dt}}}=\frac{\sqrt{2}(\mathrm{a}+\mathrm{b}) \mathrm{e}^{\mathrm{t} \sqrt{2}}}{\cos \mathrm{t}}\end{array}
$\begin{aligned} \therefore \quad & \frac{d^2 y}{d x^2}=\frac{d}{d t}\left(\frac{\sqrt{2}(a+b) e^{t \sqrt{2}}}{\cos t}\right) \cdot \frac{d t}{d x} \\ & =\sqrt{2}(a+b)\left[\frac{\cos t\left(e^{t \sqrt{2}} \cdot \sqrt{2}\right)-e^{t \sqrt{2}}(-\sin t)}{(\cos t)^2}\right] \cdot \frac{1}{\cos t}\end{aligned}\begin{aligned} & =\sqrt{2}(\mathrm{a}+\mathrm{b})\left[\frac{\mathrm{e}^{\mathrm{t} \sqrt{2}}(\sqrt{2} \cos \mathrm{t}+\sin t)}{\cos ^3 t}\right] \\ & \left(1-x^2\right) y^{\prime \prime}-x y^{\prime}\end{aligned}=\left(1-\sin ^2 t\right) \sqrt{2}(a+b)\left[\frac{e^{t \sqrt{2}}(\sqrt{2} \cos t+\sin t)}{\cos ^3 t}\right]-\sin t\left[\frac{\sqrt{2}(a+b) \mathrm{e}^{\mathrm{t} \sqrt{2}}}{\cos t}\right]\begin{array}{r}=\left(\cos ^2 t\right) \sqrt{2}(a+b)\left[\frac{e^{t \sqrt{2}}(\sqrt{2} \cos t+\sin t)}{\cos ^3 t}\right] \\ -\sin t\left[\frac{\sqrt{2}(a+b) e^{i \sqrt{2}}}{\cos t}\right]\end{array}
$\begin{aligned} & =\frac{\sqrt{2}(a+b) e^{t \sqrt{2}}(\sqrt{2} \cos t+\sin t-\sin t)}{\cos t} \\ & =\frac{\sqrt{2}(a+b) e^{t \sqrt{2}}(\sqrt{2} \cos t)}{\cos t} \\ & =2\left(a e^{t \sqrt{2}}+b e^{t \sqrt{2}}\right) \\ & = 2y \\ & \therefore=2\end{aligned}$

Acceleration $=\left(8-\frac{\mathrm{t}}{5}\right) \mathrm{cm} / \mathrm{s}^2\Rightarrow \frac{\mathrm{dv}}{\mathrm{dt}}=8-\frac{\mathrm{t}}{5}$<br/>Integrating on both sides, we get
$v=8 t-\frac{t^2}{10}+c...(i)$<br/>At $t=0, v=0\begin{array}{ll}
\therefore & 0=8(0)-0+c \Rightarrow c=0 \\
\therefore & v=8 t-\frac{t^2}{10}...ii[From(i)]
\end{array} \\ Acceleration $=0\begin{aligned}
& \Rightarrow \frac{\mathrm{dv}}{\mathrm{dt}}=0 \\
& \Rightarrow 8-\frac{\mathrm{t}}{5}=0 \\
& \Rightarrow \mathrm{t}=40
\end{aligned}$ \\ Substituting $\mathrm{t}=40$ in (ii), we get
Velocity $(v)=8(40)-\frac{(40)^2}{10}=160 \mathrm{~cm} / \mathrm{s}

$(a+\sqrt{2} b \cos x)(a-\sqrt{2} b \cos y)=a^2-b^2$<br/>Differentiating both sides w.r.t. $y$, we get
$\begin{aligned}
& \begin{aligned}
&(\mathrm{a}+\sqrt{2} \mathrm{~b} \cos x)(\sqrt{2} \mathrm{~b} \sin y) \\
& \quad+(\mathrm{a}-\sqrt{2} \mathrm{~b} \cos y)\left(-\sqrt{2} \mathrm{~b} \sin x \frac{\mathrm{~d} x}{\mathrm{~d} y}\right)=0 \\
& \Rightarrow \frac{\mathrm{~d} x}{\mathrm{~d} y}=\frac{\sqrt{2} \mathrm{~b} \sin y(\mathrm{a}+\sqrt{2} \mathrm{~b} \cos x)}{\sqrt{2} \mathrm{~b} \sin x(\mathrm{a}-\sqrt{2} \mathrm{~b} \cos y)} \\
& \Rightarrow\left(\frac{\mathrm{d} x}{\mathrm{~d} y}\right)_{\left(\frac{\pi}{4} \frac{\pi}{4}\right)}=\frac{\mathrm{b}(\mathrm{a}+\mathrm{b})}{\mathrm{b}(\mathrm{a}-\mathrm{b})}=\frac{\mathrm{a}+\mathrm{b}}{\mathrm{a}-\mathrm{b}}
\end{aligned}
\end{aligned}$

Let $y=\log _{x^2}(\log x)\therefore \quad x^{2 y}=\log x$<br/>Differentiating w.r.t. $x$, we get
$\begin{aligned}
& x^{2 y}(\log x) \times 2 \times \frac{\mathrm{d} y}{\mathrm{~d} x}=\frac{1}{x} \\
& \therefore \quad(\log x)^2 \times \frac{\mathrm{d} y}{\mathrm{~d} x}=\frac{1}{2 x} \\
& \quad \text { At } x=\mathrm{e}, \mathrm{f}^{\prime}(x)=\frac{\mathrm{d} y}{\mathrm{~d} x}=\frac{1}{2 \mathrm{e}}
\end{aligned} \quad \ldots\left[\because x^{2 y}=\log x\right]$

$\begin{array}{ll} & x^2+y^2=\mathrm{t}+\frac{1}{\mathrm{t}} \text { and } x^4+y^4=\mathrm{t}^2+\frac{1}{\mathrm{t}^2} \\ \therefore \quad & \left(x^2+y^2\right)^2=\left(\mathrm{t}+\frac{1}{\mathrm{t}}\right)^2 \\ \therefore \quad & x^4+y^4+2 x^2 y^2=\mathrm{t}^2+\frac{1}{\mathrm{t}^2}+2 \\ \therefore \quad & \mathrm{t}^2+\frac{1}{\mathrm{t}^2}+2 x^2 y^2=\mathrm{t}^2+\frac{1}{\mathrm{t}^2}+2 \\ \therefore \quad & x^2 \dot{y}^2=1 \\ \therefore \quad & y^2=\frac{1}{x^2}\end{array}
Differentiating w.r.t. $x$, we get
$\begin{aligned}
& 2 y \frac{\mathrm{~d} y}{\mathrm{~d} x}=\frac{-2}{x^3} \\
\therefore \quad & \frac{\mathrm{~d} y}{\mathrm{~d} x}=\frac{-1}{x^3 y}
\end{aligned}

$\log (x+y)=2 x y...(i)$<br/>Differentiating both sides w.r.t. $x$, we get
$\begin{aligned}
& \left(\frac{1}{x+y}\right)\left(1+\frac{\mathrm{d} y}{\mathrm{~d} x}\right)=2\left(x \frac{\mathrm{~d} y}{\mathrm{~d} x}+y\right) \\
& \Rightarrow \frac{\mathrm{d} y}{\mathrm{~d} x}=\frac{1-2 x y-2 y^2}{2 x^2+2 x y-1}
\end{aligned}$<br/>Putting $x=0$ in (i), we get
$\begin{array}{ll} 
& y=1 \\
\therefore \quad & y^{\prime}(0)=\frac{1-0-2}{0+0-1}=1
\end{array}$

$\log (x+y)=2 x y...(i)$<br/>Differentiating both sides w.r.t. $x$, we get
$\begin{aligned}
& \left(\frac{1}{x+y}\right)\left(1+\frac{\mathrm{d} y}{\mathrm{~d} x}\right)=2\left(x \frac{\mathrm{~d} y}{\mathrm{~d} x}+y\right) \\
& \Rightarrow \frac{\mathrm{d} y}{\mathrm{~d} x}=\frac{1-2 x y-2 y^2}{2 x^2+2 x y-1}
\end{aligned}$<br/>Putting $x=0$ in (i), we get
$\begin{aligned}
& y=1 \\
\therefore \quad & y^{\prime}(0)=\frac{1-0-2}{0+0-1}=1
\end{aligned}$

$y=a x^{\mathrm{n}+1}+\mathrm{b} x^{-\mathrm{n}}$<br/>Differentiating w.r.t. $x$, we get
$\begin{aligned}
& \frac{\mathrm{d} y}{\mathrm{~d} x}=\mathrm{a}(\mathrm{n}+1) x^{\mathrm{n}+1-1}+\mathrm{b}(-\mathrm{n}) x^{-\mathrm{n}-1} \\
& \frac{\mathrm{~d} y}{\mathrm{~d} x}=\mathrm{a}(\mathrm{n}+1) x^{\mathrm{n}}-\mathrm{bn} x^{-\mathrm{n}-1}
\end{aligned}$<br/>Again differentiating w.r.t. $x$, we get
$\begin{aligned}
\frac{\mathrm{d}^2 y}{\mathrm{~d} x^2} & =a(n+1)^n x^{\mathrm{n}-1}-b n(-n-1) x^{-n-1-1} \\
& =a(n+1) n x^{n-1}+b n(n+1) x^{-n-2} \\
& =n(n+1) \frac{a x^n}{x}+n(n+1) b \frac{x^{-n}}{x^2}
\end{aligned}\begin{array}{ll} & \frac{\mathrm{d}^2 y}{\mathrm{~d} x^2}=\frac{\mathrm{n}(\mathrm{n}+1)}{x^2}\left[\mathrm{a} x^{\mathrm{n}+1}+\mathrm{b} x^{-\mathrm{n}}\right] \\ \therefore \quad & x^2 \frac{\mathrm{~d}^2 y}{\mathrm{~d} x^2}=\mathrm{n}(\mathrm{n}+1) y\end{array}$

$\begin{aligned}
\mathrm{h}(x) & =\mathrm{f}(\mathrm{~g}(x)) \\
& =\mathrm{f}\left(\sin ^{-1} x\right) \\
\therefore \quad \mathrm{h}(x) & =\mathrm{e}^{\sin ^{-1} x}
\end{aligned}$<br/>Differentiating w.r.t. $x$, we get
$\begin{aligned}
\mathrm{h}^{\prime}(x) & =\mathrm{e}^{\sin ^{-1} x} \cdot \frac{\mathrm{~d}}{\mathrm{~d} x}\left(\sin ^{-1} x\right) \\
& =\mathrm{e}^{\sin ^{-1} x} \cdot \frac{1}{\sqrt{1-x^2}}
\end{aligned}$<br/>Now, $\frac{\mathrm{h}^{\prime}(x)}{\mathrm{h}(x)}=\frac{\mathrm{e}^{\sin ^{-1} x} \cdot \frac{1}{\sqrt{1-x^2}}}{\mathrm{e}^{\sin ^{-1} x}}=\frac{1}{\sqrt{1-x^2}}\therefore \quad\left(\frac{h^{\prime}(x)}{h(x)}\right)^2=\frac{1}{1-x^2}$

Let $y=\tan ^{-1}\left(\frac{6 x \sqrt{x}}{1-9 x^3}\right)\begin{aligned}
& \quad=\tan ^{-1}\left(\frac{3 x \sqrt{x}+3 x \sqrt{x}}{1-3 x \sqrt{x} \cdot 3 x \sqrt{x}}\right) \\
& \quad=\tan ^{-1}(3 x \sqrt{x})+\tan ^{-1} 3 x \sqrt{x} \\
& y=2 \tan ^{-1}(3 x \cdot \sqrt{x})
\end{aligned}$<br/>Differentiating w.r.t. $x$, we get
$\begin{aligned}
\frac{\mathrm{d} y}{\mathrm{~d} x} & =\frac{2}{1+(3 x \sqrt{x})^2} \cdot \frac{\mathrm{~d}}{\mathrm{~d} x}(3 x \cdot \sqrt{x}) \\
& =\frac{2}{1+9 x^3} \cdot \frac{9}{2} \sqrt{x} \\
\frac{\mathrm{~d} y}{\mathrm{~d} x} & =\frac{9 \sqrt{x}}{1+9 x^3}
\end{aligned}\therefore \quad$ Comparing with $\frac{\mathrm{d} y}{\mathrm{~d} x}=\sqrt{x} \cdot \mathrm{~g}(x)\therefore \quad \mathrm{g}(x)=\frac{9}{1+9 x^3}$

Let $\mathrm{u}=\mathrm{e}^x$ and $\mathrm{v}=\sqrt{x}$ Differentiating u and v w.r.t. $x$, we get
$\begin{aligned}
& \frac{\mathrm{du}}{\mathrm{dx}}=\mathrm{e}^x, \frac{\mathrm{dv}}{\mathrm{~d} x}=\frac{1}{2 \sqrt{x}} \\
\therefore \quad & \frac{\mathrm{du}}{\mathrm{dv}}=\frac{\frac{\mathrm{du}}{\mathrm{dx}}}{\frac{\mathrm{dv}}{\mathrm{dx}}}=\frac{\mathrm{e}^x}{\frac{1}{2 \sqrt{x}}}=2 \mathrm{e}^x \sqrt{x}
\end{aligned}$

$8 f(x)+6 f\left(\frac{1}{x}\right)=x+5...(i)$<br/>Differentiating w.r.t. $x$, we get
$8 f^{\prime}(x)+6 f^{\prime}\left(\frac{1}{x}\right)\left(\frac{-1}{x^2}\right)=1...(ii)$<br/>Substituting $x=-1$ in (i), we get $8 f(-1)+6 f(-1)=4\begin{array}{ll}
\therefore & 14 f(-1)=4 \\
\therefore & f(-1)=\frac{4}{14}=\frac{2}{7}...(iii)
\end{array} \\ Substituting $x=-1$ in (ii), we get
$\begin{aligned}
& \mathrm{f}^{\prime}(-1)=\frac{1}{2} \\.
& y=x^2 \mathrm{f}(x)
\end{aligned}$...(iv)
$\begin{aligned} \therefore \quad \frac{\mathrm{d} y}{\mathrm{~d} x} & =2 \\ \left.\therefore \quad \frac{\mathrm{~d} y}{\mathrm{~d} x}\right|_{x=-1} & =2(-1)+x^2 \mathrm{f}^{\prime}(x) \\ & =\frac{-4}{7}+\frac{1}{2} \quad \ldots[\text { From (iii) and (iv) }] \\ & =-\frac{1}{14}\end{aligned}

$\begin{array}{ll}
y= & \left((x+1)(4 x+1)(9 x+1) \ldots\left(\mathrm{n}^2 x+1\right)\right)^2 \\
\therefore \quad & \log y=2[\log (x+1)+\log (4 x+1)+\log (9 x+1) \\
& \left.+\ldots+\log \left(\mathrm{n}^2 x+1\right)\right]
\end{array}
Differentiating w.r.t. $x$, we get
$\frac{1}{y} \frac{\mathrm{~d} y}{\mathrm{~d} x}=2\left[\frac{1}{(x+1)}+\frac{4}{4 x+1}+\frac{9}{9 x+1}+\ldots+\frac{\mathrm{n}^2}{\mathrm{n}^2 \dot{x}+1}\right]\therefore \quad \frac{\mathrm{d} y}{\mathrm{~d} x}=2 y\left[\frac{(1)^2}{x+1}+\frac{(2)^2}{4 x+1}+\frac{(3)^2}{9 x+1}+\ldots+\frac{\mathrm{n}^2}{\mathrm{n}^2 x+1}\right]\begin{aligned}\left.\therefore \quad \frac{\mathrm{d} y}{\mathrm{~d} x}\right|_{x=0} & =2 y(0)\left[1^2+2^2+3^2+\ldots+\mathrm{n}^2\right] \\ & =2(1) \frac{\mathrm{n}(\mathrm{n}+1)(2 \mathrm{n}+1)}{6} \\ & =\frac{\mathrm{n}(\mathrm{n}+1)(2 \mathrm{n}+1)}{3}\end{aligned}

$\begin{aligned} y & =\tan ^{-1}\left(\frac{3+2 x}{2-3 x}\right)+\tan ^{-1}\left(\frac{3 x}{1+4 x^2}\right) \\ & =\tan ^{-1}\left(\frac{\frac{3}{2}+x}{1-\frac{3}{2} x}\right)+\tan ^{-1}\left(\frac{4 x-x}{1+(4 x)(x)}\right)\end{aligned}\begin{aligned} & =\tan ^{-1}\left(\frac{3}{2}\right)+\tan ^{-1} x+\tan ^{-1} 4 x-\tan ^{-1} x \\ \therefore \quad y & =\tan ^{-1}\left(\frac{3}{2}\right)+\tan ^{-1}(4 x)\end{aligned}$
Differentiating w.r.t. $x$, we get
$\begin{aligned}
& \frac{\mathrm{d} y}{\mathrm{~d} x}=0+\frac{4}{1+(4 x)^2} \\
& \Rightarrow \frac{\mathrm{~d} y}{\mathrm{~d} x}=\frac{4}{1+16 x^2}
\end{aligned}$

$y=\sqrt{\frac{1-\sin ^{-1} x}{1+\sin ^{-1} x}}$<br/>Differentiating w.r.t. $x$, we get
$\begin{aligned}
\frac{\mathrm{d} y}{\mathrm{~d} x} & =\frac{\mathrm{d}}{\mathrm{~d} x}\left(\sqrt{\frac{1-\sin ^{-1} x}{1+\sin ^{-1} x}}\right) \\
& =\frac{1}{2 \sqrt{\frac{1-\sin ^{-1} x}{1+\sin ^{-1} x}}} \cdot \frac{\mathrm{~d}}{\mathrm{~d} x}\left(\frac{1-\sin ^{-1} x}{1+\sin ^{-1} x}\right) \\
& =\frac{\sqrt{1+\sin ^{-1} x}}{2 \sqrt{1-\sin ^{-1} x}}
\end{aligned}\begin{aligned} & \frac{\left(1+\sin ^{-1} x\right) \cdot \frac{d}{d x}\left(1-\sin ^{-1} x\right)-\left(1-\sin ^{-1} x\right) \frac{d}{d x}\left(1+\sin ^{-1} x\right)}{\left(1+\sin ^{-1} x\right)^2} \\ & =\frac{\sqrt{1+\sin ^{-1} x}}{2 \sqrt{1-\sin ^{-1} x}} \cdot \frac{\left(1+\sin ^{-1} x\right) \times \frac{-1}{\sqrt{1-x^2}}-\left(1-\sin ^{-1} x\right) \cdot \frac{1}{\sqrt{1-x^2}}}{\left(1+\sin ^{-1} x\right)^2}\end{aligned}\begin{aligned} &=\frac{\sqrt{1+\sin ^{-1} x}}{2 \sqrt{1-\sin ^{-1} x}} \times \frac{\frac{1}{\sqrt{1-x^2}}\left[-1-\sin ^{-1} x-1+\sin ^{-1} x\right]}{\left(1+\sin ^{-1} x\right)^2} \\ & \frac{\mathrm{~d} y}{\mathrm{~d} x}=\frac{(-1) \sqrt{1+\sin ^{-1} x}}{\sqrt{1-\sin ^{-1} x} \cdot\left(\sqrt{1-x^2}\right)\left(1+\sin ^{-1} x\right)^2} \\ &\left(\frac{\mathrm{~d} y}{\mathrm{~d} x}\right)_{\mathrm{at} x=0}=\frac{-1 \sqrt{1+\sin ^{-1} 0}}{\left(\sqrt{1-\sin ^1 0}\right)\left(\sqrt{1-0^2}\right)\left(1+\sin ^{-1} 0\right)^2} \\ &=\frac{-1}{(1)(1)(1+0)} \\ & \therefore \quad\left(\frac{\mathrm{d} y}{\mathrm{~d} x}\right)_{\mathrm{at} x=0}=-1\end{aligned}$

$\begin{aligned}
x y & =\sqrt{\mathrm{e}^{\sin ^{-1} \mathrm{t}}} \cdot \sqrt{\mathrm{e}^{\cos ^{-1} \mathrm{t}}} \\
& =\sqrt{\mathrm{e}^{\sin ^{-1} \mathrm{t}+\cos ^{-1} \mathrm{t}}} \\
\therefore \quad x y & =\sqrt{\mathrm{e}^{\frac{\pi}{2}}}
\end{aligned}$
Differentiating both sides w.r.t. $x$, we get
$\begin{aligned}
& x \frac{\mathrm{d} y}{\mathrm{~d} x}+y \cdot 1=0 \\
& \Rightarrow \frac{\mathrm{d} y}{\mathrm{~d} x}=-\frac{y}{x}...(i)
\end{aligned}\begin{aligned} \Rightarrow \frac{\mathrm{d}^2 y}{\mathrm{~d} x^2} & =-\left(\frac{x \frac{\mathrm{d} y}{\mathrm{~d} x}-y \cdot 1}{x^2}\right) \\ \Rightarrow \frac{\mathrm{d}^2 y}{\mathrm{~d}^2} & =-\left(\frac{x\left(-\frac{y}{x}\right)-y}{x^2}\right)... [From (i)] \\ & =\frac{2 y}{x^2}\end{aligned}$

$\begin{array}{ll} & \mathrm{f}(x)=x^3+x^2 \mathrm{f}^{\prime}(1)+x \mathrm{f}^{\prime \prime}(2)+6 \\ \therefore \quad & \mathrm{f}^{\prime}(x)=3 x^2+2 x \mathrm{f}^{\prime}(1)+\mathrm{f}^{\prime \prime}(2) \\ \therefore \quad & \mathrm{f}^{\prime \prime}(x)=6 x+2 \mathrm{f}^{\prime}(1)\end{array}
Substituting $x=1$ in (i), we get

\begin{aligned}
& \mathrm{f}^{\prime}(1)=3(1)^2+2(1) \mathrm{f}^{\prime}(1)+\mathrm{f}^{\prime \prime}(2) \\
& \Rightarrow \mathrm{f}^{\prime}(1)+\mathrm{f}^{\prime \prime}(2)=-3
\end{aligned}

Substituting $x=2$ in (ii), we get

\begin{aligned}
& \mathrm{f}^{\prime \prime}(2)=6(2)+2 \mathrm{f}^{\prime}(1) \\
& \Rightarrow \mathrm{f}^{\prime \prime}(2)=12+2 \mathrm{f}^{\prime}(1)
\end{aligned}

From (iii) and (iv), we get

\begin{aligned}
& \mathrm{f}^{\prime}(1)+12+2 \mathrm{f}^{\prime}(1)=-3 \\
& \Rightarrow 3 \mathrm{f}^{\prime}(1)=-15 \\
& \Rightarrow \mathrm{f}^{\prime}(1)=-5 \\
& \text { From (iii) },-5+\mathrm{f}^{\prime \prime}(2)=-3 \\
& \Rightarrow \mathrm{f}^{\prime \prime}(2)=2
\end{aligned}

$\begin{aligned} \therefore \quad \mathrm{f}(2) & =2^3+2^2(-5)+2(2)^{\prime}+6 \\ & =8-20+4+6 \\ & =-2\end{aligned}

\begin{aligned}
& y=[(x+1)(2 x+1)(3 x+1) \ldots(\mathrm{n} x+1)]^{\mathrm{n}} \\
& \Rightarrow \log y=\operatorname{nlog}[(x+1)(2 x+1)(3 x+1) \\
& \Rightarrow \log y=\mathrm{n}[\log (x+1)+\log (2 x+1) \\
& \quad+\log (3 x+1)+\ldots+\log (\mathrm{n} x+1)]
